package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"

	"github.com/goavro/goavro"
)

// Convert a given Go struct definition to an Avro schema.
func convertGoStructToAvroSchema(file string, structName string) error {
	// Read the Go file containing the struct
	fileData, err := ioutil.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading file %s: %w", file, err)
	}

	// Parse the Go code to extract the struct definition
	var structDef goavro.StructDefinition
	err = json.Unmarshal(fileData, &structDef)
	if err != nil {
		return fmt.Errorf("unmarshaling JSON data: %w", err)
	}

	// Create an Avro schema based on the parsed struct definition
	schema, err := goavro.NewSchemaFromDefinition(structDef)
	if err != nil {
		return fmt.Errorf("creating Avro schema from struct definition: %w", err)
	}

	// Write the generated Avro schema to a file
	outputFile := "struct." + structName + ".avsc"
	err = ioutil.WriteFile(outputFile, []byte(schema), 0644)
	if err != nil {
		return fmt.Errorf("writing Avro schema to file %s: %w", outputFile, err)
	}
	fmt.Printf("Generated Avro schema saved to %s\n", outputFile)
	return nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run main.go <file> <struct>")
		os.Exit(1)
	}

	file := os.Args[1]
	structName := os.Args[2]

	if err := convertGoStructToAvroSchema(file, structName); err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}
}
```

